import { describe, it, expect, vi, beforeEach } from 'vitest';
import { ExtensionToWebviewMessage, WebviewToExtensionMessage } from '../types';

describe('Extension-Webview Message Protocol', () => {
  describe('Message Type Definitions', () => {
    it('should have all required webview-to-extension message types', () => {
      const requiredTypes = [
        'sendMessage',
        'acceptReview',
        'rejectReview',
        'clearChat',
        'abort',
        'getSessions',
        'loadSession',
        'deleteSession',
        'switchAgent',
        'listProviders',
        'setApiKey',
        'removeApiKey',
        'searchFiles',
        'getSavedModel',
        'saveModel',
        'revertMessage',
        'unrevert',
        'respondPermission',
        'respondReadPermission',
        'openDiff',
        'runCommand',
        'loadSkills',
        'webviewReady',
      ];

      const typeMap: Record<string, boolean> = {};
      for (const t of requiredTypes) {
        typeMap[t] = true;
      }

      expect(typeMap['sendMessage']).toBe(true);
      expect(typeMap['webviewReady']).toBe(true);
    });

    it('should have all required extension-to-webview message types', () => {
      const requiredTypes = [
        'receiveMessage',
        'receiveChunk',
        'streamEnd',
        'reviewReady',
        'reviewResolved',
        'status',
        'gitInfo',
        'projectInfo',
        'sessionList',
        'sessionLoaded',
        'sessionDeleted',
        'agentList',
        'error',
        'providerList',
        'providerUpdated',
        'fileSearchResults',
        'savedModel',
        'toolEvent',
        'revertResult',
        'messageMeta',
        'reasoningContent',
        'readFilePrompt',
        'skillList',
      ];

      expect(requiredTypes.length).toBeGreaterThan(20);
    });
  });

  describe('Message Payload Validation', () => {
    it('should validate sendMessage payload structure', () => {
      const validPayload: WebviewToExtensionMessage['payload'] = {
        prompt: 'Hello world',
        model: 'openai/gpt-4',
        mode: 'build',
        context: [
          { type: 'file', path: 'src/index.ts' },
        ],
      };

      expect(validPayload.prompt).toBeDefined();
      expect(validPayload.mode).toBeDefined();
    });

    it('should validate toolEvent payload structure', () => {
      const validPayload: ExtensionToWebviewMessage['payload'] = {
        id: 'tool-123',
        type: 'tool_call',
        name: 'read',
        status: 'running',
        content: 'Reading file...',
        meta: { path: 'src/index.ts' },
      };

      expect(validPayload.type).toBe('tool_call');
      expect(validPayload.status).toBe('running');
    });

    it('should validate receiveChunk payload structure', () => {
      const validPayload: ExtensionToWebviewMessage['payload'] = {
        content: 'Hello',
        fullContent: 'Hello world',
      };

      expect(validPayload.content).toBeDefined();
    });
  });

  describe('Session Flow', () => {
    it('should track session lifecycle', () => {
      const sessionStates: string[] = [];

      sessionStates.push('created');
      sessionStates.push('active');
      sessionStates.push('idle');

      expect(sessionStates).toContain('created');
      expect(sessionStates).toContain('idle');
    });
  });

  describe('Streaming Flow', () => {
    it('should handle streaming message sequence', () => {
      const messages: string[] = [];

      messages.push('receiveMessage:assistant:empty');
      messages.push('receiveChunk:Hello');
      messages.push('receiveChunk: world');
      messages.push('streamEnd:Hello world');

      expect(messages[0]).toContain('receiveMessage');
      expect(messages[3]).toContain('streamEnd');
    });

    it('should handle tool events during streaming', () => {
      const events: any[] = [];

      events.push({ type: 'tool_call', name: 'read', status: 'running' });
      events.push({ type: 'file_read', name: 'read', status: 'completed' });
      events.push({ type: 'tool_result', name: 'read', status: 'completed' });

      expect(events[0].status).toBe('running');
      expect(events[1].type).toBe('file_read');
    });
  });

  describe('Permission Flow', () => {
    it('should handle permission request flow', () => {
      const permission = {
        id: 'perm-123',
        type: 'read',
        patterns: ['**/.env'],
        response: 'allow',
        remember: true,
      };

      expect(permission.response).toBe('allow');
      expect(permission.remember).toBe(true);
    });

    it('should handle read permission request flow', () => {
      const readPerm = {
        filePath: 'config/.env',
        response: 'deny',
        requestId: 'req-456',
      };

      expect(readPerm.response).toBe('deny');
    });
  });
});

import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import { SidebarProvider } from '../providers/SidebarProvider';
import * as vscode from 'vscode';

vi.mock('vscode', () => ({
  workspace: {
    workspaceFolders: [{ uri: { fsPath: '/test/workspace' } }],
    fs: {
      readFile: vi.fn(),
      readDirectory: vi.fn(),
    },
  },
  window: {
    registerWebviewViewProvider: vi.fn(),
    showTextDocument: vi.fn(),
  },
  Uri: {
    joinPath: vi.fn(),
    file: vi.fn(),
  },
  EventEmitter: vi.fn(),
}));

describe('SidebarProvider Message Handling', () => {
  let provider: SidebarProvider;
  let mockContext: any;
  let extensionUri: vscode.Uri;

  beforeEach(() => {
    mockContext = {
      extensionUri: { fsPath: '/test/ext' },
      secrets: {
        get: vi.fn().mockResolvedValue(undefined),
        store: vi.fn().mockResolvedValue(undefined),
        delete: vi.fn().mockResolvedValue(undefined),
      },
      subscriptions: [],
    };
    extensionUri = { fsPath: '/test/ext' } as any;
    provider = new SidebarProvider(extensionUri, mockContext);
  });

  describe('Message Type Validation', () => {
    it('should accept valid message types', () => {
      const validTypes = [
        'sendMessage',
        'searchFiles',
        'listProviders',
        'setApiKey',
        'loadSkills',
      ];

      for (const type of validTypes) {
        expect(validTypes).toContain(type);
      }
    });
  });

  describe('Payload Validation', () => {
    it('should validate searchFiles payload', () => {
      const isValid = provider.validatePayload('searchFiles', { query: '*.ts' });
      expect(isValid).toBe(true);
    });

    it('should reject searchFiles with missing query', () => {
      const isValid = provider.validatePayload('searchFiles', {});
      expect(isValid).toBe(false);
    });

    it('should validate setApiKey payload', () => {
      const isValid = provider.validatePayload('setApiKey', { providerId: 'openai', key: 'sk-123' });
      expect(isValid).toBe(true);
    });

    it('should reject setApiKey with missing fields', () => {
      const isValid = provider.validatePayload('setApiKey', { providerId: 'openai' });
      expect(isValid).toBe(false);
    });

    it('should validate runCommand payload', () => {
      const isValid = provider.validatePayload('runCommand', { command: 'init' });
      expect(isValid).toBe(true);
    });

    it('should validate loadSession payload', () => {
      const isValid = provider.validatePayload('loadSession', { sessionId: 'sess-123' });
      expect(isValid).toBe(true);
    });
  });

  describe('Message Type Mapping', () => {
    it('should have handlers for all WEBVIEW_TO_EXTENSION_TYPES', () => {
      const handlers = [
        'searchFiles',
        'getSavedModel',
        'saveModel',
        'revertMessage',
        'unrevert',
        'respondPermission',
        'respondReadPermission',
        'loadSkills',
        'runCommand',
        'webviewReady',
        'sendMessage',
        'acceptReview',
        'rejectReview',
        'clearChat',
        'abort',
        'getSessions',
        'loadSession',
        'deleteSession',
        'switchAgent',
        'listProviders',
        'setApiKey',
        'removeApiKey',
        'openDiff',
      ];

      expect(handlers.length).toBe(23);
    });
  });
});

import {
  ProviderListResult,
  AgentRaw,
  normalizeAgentId,
  ProviderAuthMap,
  RawSessionMessage,
  RevertResult,
  UnrevertResult,
  SendPromptBody,
  isRecord,
  getErrorMessage,
} from '../types';
import { NormalizedDiff, normalizeDiff } from '../utils/diffUtils';

export interface ApiClientOptions {
  baseUrl: string;
  authHeader: Record<string, string>;
}

/**
 * HTTP client for the opencode server REST API.
 * Wraps fetch with auth headers and error handling.
 */
export class ApiClient {
  private baseUrl: string;
  private authHeader: Record<string, string>;

  constructor(options: ApiClientOptions) {
    this.baseUrl = options.baseUrl;
    this.authHeader = options.authHeader;
  }

  updateAuth(baseUrl: string, authHeader: Record<string, string>): void {
    this.baseUrl = baseUrl;
    this.authHeader = authHeader;
  }

  private async fetch<T = unknown>(path: string, options: RequestInit = {}): Promise<T> {
    const url = `${this.baseUrl}${path}`;
    const response = await fetch(url, {
      ...options,
      headers: {
        'Content-Type': 'application/json',
        ...this.authHeader,
        ...options.headers,
      },
    });

    if (!response.ok) {
      const text = await response.text();
      const isJson = text.startsWith('{') || text.startsWith('[');
      const safeMsg = isJson && text.includes('"error"') ? 'JSON error response' : text.slice(0, 100);
      console.error(`[opencode:api] ${options.method || 'GET'} ${path} -> ${response.status}: ${safeMsg}`);
      throw new Error(`OpenCode API request failed (HTTP ${response.status})`);
    }

    const contentType = response.headers.get('content-type') || '';
    if (contentType.includes('application/json')) {
      return response.json() as Promise<T>;
    }

    return response.text() as unknown as T;
  }

  async createSession(title?: string): Promise<{ id: string; title?: string }> {
    const data = await this.fetch<{ id: string; title?: string }>('/session', {
      method: 'POST',
      body: JSON.stringify({
        title: title || `VS Code - ${new Date().toLocaleString()}`,
      }),
    });
    return { id: data.id, title: data.title };
  }

  async listSessions(): Promise<{ id: string; title?: string }[]> {
    const data = await this.fetch<{ id: string; title?: string }[]>('/session');
    return Array.isArray(data) ? data : [];
  }

  async getSessionDiff(sessionId: string): Promise<NormalizedDiff[]> {
    const result = await this.fetch<{ files?: unknown[] } | unknown[]>(`/session/${sessionId}/diff`);
    let arr: unknown[] = [];
    if (Array.isArray(result)) {
      arr = result;
    } else if (isRecord(result) && Array.isArray(result['files'])) {
      arr = result['files'] as unknown[];
    }
    const normalized = arr.map(normalizeDiff);
    return normalized;
  }

  async getSessionMessages(sessionId: string): Promise<RawSessionMessage[]> {
    try {
      const data = await this.fetch<unknown>(`/session/${sessionId}/message`);
      return Array.isArray(data) ? (data as RawSessionMessage[]) : [];
    } catch {
      return [];
    }
  }

  async deleteSession(sessionId: string): Promise<boolean> {
    try {
      await this.fetch(`/session/${sessionId}`, { method: 'DELETE' });
      return true;
    } catch {
      return false;
    }
  }

  async getAgents(): Promise<string[]> {
    try {
      const result = await this.fetch<unknown>('/agent');
      if (Array.isArray(result)) {
        return (result as AgentRaw[]).map(normalizeAgentId).filter(Boolean);
      }
      if (isRecord(result) && Array.isArray(result['agents'])) {
        return (result['agents'] as AgentRaw[]).map(normalizeAgentId).filter(Boolean);
      }
      return [];
    } catch {
      return [];
    }
  }

  async getCurrentProject(): Promise<import('../types').ProjectInfo | null> {
    try {
      return await this.fetch<import('../types').ProjectInfo>('/project/current');
    } catch {
      return null;
    }
  }

  async getPath(): Promise<import('../types').PathInfo | null> {
    try {
      return await this.fetch<import('../types').PathInfo>('/path');
    } catch {
      return null;
    }
  }

  async getVcsInfo(): Promise<import('../types').VcsInfo | null> {
    try {
      return await this.fetch<import('../types').VcsInfo>('/vcs');
    } catch {
      return null;
    }
  }

  async listProviders(): Promise<ProviderListResult> {
    return this.fetch('/provider');
  }

  async getProviderAuth(): Promise<ProviderAuthMap> {
    return this.fetch('/provider/auth');
  }

  async setAuth(providerId: string, key: string): Promise<boolean> {
    try {
      const response = await fetch(`${this.baseUrl}/auth/${providerId}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json', ...this.authHeader },
        body: JSON.stringify({ type: 'api', key }),
      });
      return response.ok;
    } catch {
      return false;
    }
  }

  async removeAuth(providerId: string): Promise<boolean> {
    try {
      const response = await fetch(`${this.baseUrl}/auth/${providerId}`, {
        method: 'DELETE',
        headers: { ...this.authHeader },
      });
      return response.ok;
    } catch {
      return false;
    }
  }

  async summarizeSession(sessionId: string, providerID: string, modelID: string): Promise<boolean> {
    try {
      const result = await this.fetch(`/session/${sessionId}/summarize`, {
        method: 'POST',
        body: JSON.stringify({ providerID, modelID, auto: false }),
      });
      return result === true || result === 'true';
    } catch {
      return false;
    }
  }

  async revertSession(sessionId: string, messageId: string): Promise<RevertResult | null> {
    try {
      return await this.fetch<RevertResult>(`/session/${sessionId}/revert`, {
        method: 'POST',
        body: JSON.stringify({ messageID: messageId }),
      });
    } catch {
      return null;
    }
  }

  async unrevertSession(sessionId: string): Promise<UnrevertResult | null> {
    try {
      return await this.fetch<UnrevertResult>(`/session/${sessionId}/unrevert`, {
        method: 'POST',
      });
    } catch {
      return null;
    }
  }

  async respondPermission(sessionID: string, permissionId: string, response: string, remember?: boolean): Promise<boolean> {
    try {
      const url = `${this.baseUrl}/session/${sessionID}/permissions/${permissionId}`;
      const res = await fetch(url, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', ...this.authHeader },
        body: JSON.stringify({ response, remember: remember ?? false }),
      });
      return res.ok;
    } catch {
      return false;
    }
  }

  async abortSession(sessionId: string): Promise<void> {
    try {
      await this.fetch(`/session/${sessionId}/abort`, { method: 'POST' });
    } catch {
      // ignore
    }
  }

  async grantPermission(sessionID: string, permissionId: string): Promise<void> {
    try {
      const url = `${this.baseUrl}/session/${sessionID}/permissions/${permissionId}`;
      const response = await fetch(url, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', ...this.authHeader },
        body: JSON.stringify({ response: 'always', remember: true }),
      });
      if (response.ok) {
      } else {
        const text = await response.text();
        console.error('[opencode] Permission grant failed:', response.status, text.slice(0, 200));
      }
    } catch (err: unknown) {
      console.error('[opencode] Failed to grant permission:', getErrorMessage(err));
    }
  }

  async postMessage(sessionId: string, body: SendPromptBody, signal?: AbortSignal): Promise<Response> {
    const url = `${this.baseUrl}/session/${sessionId}/message`;
    const response = await fetch(url, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', ...this.authHeader },
      body: JSON.stringify(body),
      signal,
    });

    if (!response.ok) {
      const text = await response.text();
      throw new Error(`HTTP ${response.status}: ${text.slice(0, 200)}`);
    }

    return response;
  }
}

import { spawn, ChildProcess } from 'node:child_process';
import { access } from 'node:fs/promises';
import { resolve } from 'node:path';
import { randomBytes } from 'node:crypto';
import {
  ProviderListResult,
  ProjectInfo,
  PathInfo,
  VcsInfo,
  ProviderAuthMap,
  RawSessionMessage,
  RevertResult,
  UnrevertResult,
  SendPromptBody,
  SendPromptPart,
  getErrorMessage,
} from '../types';
import { ApiClient } from './ApiClient';
import { SseStream, SSEMessage } from './SseStream';
import { EventDispatcher, EventCallbacks } from './EventDispatcher';
import { NormalizedDiff } from '../utils/diffUtils';

interface OpencodeServerInfo {
  port: number;
  password: string;
  url: string;
}

interface SessionInfo {
  id: string;
  title?: string;
}

type EventHandler = (event: SSEMessage) => void;

/**
 * Opencode CLI wrapper that manages the server process, HTTP API client,
 * SSE streaming, and event dispatching for the VS Code extension.
 */
export class OpencodeCli {
  private process: ChildProcess | null = null;
  private server: OpencodeServerInfo | null = null;
  private readonly eventHandlers: Set<EventHandler> = new Set();
  private abortController: AbortController | null = null;
  private binaryCandidates: string[] = [];
  private readonly cwd: string | undefined;
  private apiClient: ApiClient | null = null;
  private readonly sseStream: SseStream;
  private eventDispatcher: EventDispatcher | null = null;
  private readonly idleResolveRefs = new Map<string, () => void>();

  constructor(cwd?: string) {
    this.cwd = cwd;
    this.sseStream = new SseStream();
  }

  /**
   * Ordered list of candidate binaries instead of a single one.
   * The env-var override comes first, but a stale OPENCODE_BIN_PATH
   * (e.g. left behind by an old npm install) must not hard-fail startup:
   * if it fails at serve time we fall through to the next candidate.
   */
  private async resolveBinaryCandidates(): Promise<string[]> {
    const existing: string[] = [];

    // Priority 1: explicit env var override (restricted to allowed directories)
    const envPath = process.env.OPENCODE_BIN_PATH;
    if (envPath) {
      try {
        await access(envPath);
        {
          const allowedRoots = [
            process.env.HOME || process.env.USERPROFILE || '',
            process.env.LOCALAPPDATA || '',
            process.env.APPDATA || '',
            process.env.SystemRoot || '',
            process.env.WINDIR || '',
            '/usr/local',
            '/usr/bin',
            '/bin',
            '/usr/lib',
          ].filter(Boolean);
          const resolvedPath = resolve(envPath).replaceAll('\\', '/').toLowerCase();
          const isAllowed = allowedRoots.some(root => resolvedPath.startsWith(root.replaceAll('\\', '/').toLowerCase()));
          if (isAllowed) existing.push(envPath);
          else console.warn('[opencode] OPENCODE_BIN_PATH not in allowed directories:', envPath);
        }
      } catch (err) { console.warn('[opencode] Binary path check failed:', err); }
    }

    // Priority 2: platform-specific candidates
    const candidates: string[] = [];
    const platform = process.platform;
    const home = process.env.HOME || process.env.USERPROFILE;
    const npmPrefix = process.env.npm_config_prefix;

    if (platform === 'win32') {
      const appData = process.env.APPDATA;
      // npm global installations only
      if (appData) candidates.push(String.raw`${appData}\npm\node_modules\opencode-ai\node_modules\opencode-windows-x64\bin\opencode.exe`);
      if (appData) candidates.push(String.raw`${appData}\npm\node_modules\opencode-ai\node_modules\opencode-windows-x64-baseline\bin\opencode.exe`);
    } else if (platform === 'darwin') {
      // macOS npm global + common package managers
      if (npmPrefix) candidates.push(`${npmPrefix}/bin/opencode`);
      if (home) candidates.push(`${home}/.npm-global/bin/opencode`);
      if (home) candidates.push(`${home}/.local/bin/opencode`);
      candidates.push(
        '/usr/local/bin/opencode',
        '/opt/homebrew/bin/opencode',
        '/opt/local/bin/opencode',
        '/usr/bin/opencode',
      );
    } else {
      // Linux and other Unix
      if (npmPrefix) candidates.push(`${npmPrefix}/bin/opencode`);
      if (home) candidates.push(`${home}/.local/bin/opencode`);
      if (home) candidates.push(`${home}/.local/share/opencode/bin/opencode`);
      candidates.push(
        '/usr/local/bin/opencode',
        '/snap/bin/opencode',
        '/usr/bin/opencode',
        '/bin/opencode',
      );
    }

    for (const candidate of candidates) {
      if (!candidate) continue;
      try {
        await access(candidate);
        existing.push(candidate);
      } catch {
        // Candidate does not exist or is not accessible.
      }
    }

    // Priority 3: let Node.js resolve from PATH
    existing.push('opencode');

    // De-duplicate while preserving priority order
    return [...new Set(existing)];
  }

  get authHeader(): Record<string, string> {
    if (!this.server) return {};
    const encoded = Buffer.from(`opencode:${this.server.password}`).toString('base64');
    return { Authorization: `Basic ${encoded}` };
  }

  private ensureApiClient(): ApiClient {
    if (!this.server) throw new Error('Opencode server not running');
    if (this.apiClient) {
      this.apiClient.updateAuth(this.server.url, this.authHeader);
    } else {
      this.apiClient = new ApiClient({
        baseUrl: this.server.url,
        authHeader: this.authHeader,
      });
    }
    return this.apiClient;
  }

  /**
   * Starts the opencode server process if not already running.
   * Tries each resolved binary candidate in priority order (`OPENCODE_BIN_PATH`
   * first, then platform-specific installs, then PATH) so one stale install
   * cannot break startup for everyone. Spawns `opencode serve --port 0` with
   * a generated password for Basic Auth.
   * @throws Error (including captured stderr) if every candidate fails or the
   *         server does not start within the 30s total timeout
   */
  async start(): Promise<void> {
    if (this.server) return;

    if (this.binaryCandidates.length === 0) {
      this.binaryCandidates = await this.resolveBinaryCandidates();
    }

    const password = randomBytes(16).toString('hex');
    const deadline = Date.now() + 30000;
    const failures: string[] = [];

    for (const binary of this.binaryCandidates) {
      const remaining = deadline - Date.now();
      if (remaining <= 0) break;
      try {
        await this.tryStart(binary, password, remaining);
        return;
      } catch (err: unknown) {
        failures.push(`${binary}: ${getErrorMessage(err)}`);
        console.warn('[opencode] serve failed with candidate', binary, '-', getErrorMessage(err));
      }
    }

    const detail = failures.length > 1 ? ` (${failures.join(' | ')})` : '';
    throw new Error(`opencode serve failed${detail || ': no binary candidates'}`);
  }

  /**
   * Single start attempt against one binary candidate.
   * Resolves once the server prints its listening URL; rejects on spawn error,
   * early exit, or timeout ÔÇö with the captured stderr appended so the real
   * cause (e.g. an invalid opencode.json) reaches the UI instead of a bare
   * "exited with code 1".
   */
  private tryStart(binary: string, password: string, timeoutMs: number): Promise<void> {
    return new Promise((resolve, reject) => {
      const minimalEnv: Record<string, string | undefined> = {
        OPENCODE_SERVER_PASSWORD: password,
        PATH: process.env.PATH,
        USERPROFILE: process.env.USERPROFILE,
        APPDATA: process.env.APPDATA,
        LOCALAPPDATA: process.env.LOCALAPPDATA,
        SYSTEMROOT: process.env.SYSTEMROOT,
        TEMP: process.env.TEMP,
        TMP: process.env.TMP,
        OPENCODE_SERVER_USERNAME: process.env.OPENCODE_SERVER_USERNAME || 'opencode',
        OPENCODE_CLIENT: process.env.OPENCODE_CLIENT,
        OPENCODE_DISABLE_EMBEDDED_WEB_UI: process.env.OPENCODE_DISABLE_EMBEDDED_WEB_UI,
        OPENCODE_EXPERIMENTAL_FILEWATCHER: process.env.OPENCODE_EXPERIMENTAL_FILEWATCHER,
        OPENCODE_EXPERIMENTAL_ICON_DISCOVERY: process.env.OPENCODE_EXPERIMENTAL_ICON_DISCOVERY,
        OPENCODE_BIN_PATH: process.env.OPENCODE_BIN_PATH,
      };
      for (const key of Object.keys(minimalEnv)) {
        if (minimalEnv[key] === undefined) delete minimalEnv[key];
      }

      let proc: ChildProcess;
      try {
        proc = spawn(binary, ['serve', '--port', '0'], {
          stdio: ['ignore', 'pipe', 'pipe'],
          cwd: this.cwd,
          env: minimalEnv,
        });
      } catch (err: unknown) {
        reject(err instanceof Error ? err : new Error(getErrorMessage(err)));
        return;
      }

      let started = false;
      let outputBuffer = '';
      let stderrTail = '';

      const fail = (msg: string) => {
        if (started) return;
        const stderr = stderrTail.trim().replace(/\s+/g, ' ').slice(-500);
        reject(new Error(stderr ? `${msg} ÔÇö ${stderr}` : msg));
      };

      proc.stdout?.on('data', (data: Buffer) => {
        const text = data.toString();
        outputBuffer += text;

        const match = new RegExp(/http:\/\/127\.0\.0\.1:(\d+)/).exec(outputBuffer);
        if (match && !started) {
          started = true;
          const port = Number.parseInt(match[1], 10);
          this.server = { port, password, url: `http://127.0.0.1:${port}` };
          this.process = proc;
          resolve();
        }
      });

      proc.stderr?.on('data', (data: Buffer) => {
        const text = data.toString().trim();
        if (text) {
          console.error('[opencode:err]', text);
          stderrTail = (stderrTail + '\n' + text).slice(-2000);
        }
      });

      proc.on('error', (err: Error) => {
        fail(err.message);
      });

      proc.on('exit', (code: number | null) => {
        if (!started) {
          fail(`opencode serve exited with code ${code}`);
          return;
        }
        this.server = null;
        for (const resolve of this.idleResolveRefs.values()) {
          resolve();
        }
        this.idleResolveRefs.clear();
      });

      setTimeout(() => {
        if (!started) {
          proc.kill();
          fail('opencode serve timeout');
        }
      }, timeoutMs);
    });
  }

  get isRunning(): boolean {
    return this.server !== null;
  }

  get url(): string | null {
    return this.server?.url ?? null;
  }

  /**
   * Creates a new chat session.
   * @param title - Optional session title
   * @returns Session ID and title
   */
  async createSession(title?: string): Promise<SessionInfo> {
    await this.start();
    const data = await this.ensureApiClient().createSession(title);
    return { id: data.id, title: data.title };
  }

  async listSessions(): Promise<SessionInfo[]> {
    await this.start();
