import { describe, it, expect, vi, beforeEach } from 'vitest';
import { SseStream } from './SseStream';

describe('SseStream', () => {
  const mockFetch = vi.fn();

  beforeEach(() => {
    vi.stubGlobal('fetch', mockFetch);
  });

  it('should parse data: lines', async () => {
    const encoder = new TextEncoder();
    const mockReader = {
      read: vi.fn()
        .mockResolvedValueOnce({ done: false, value: encoder.encode('data: {"type":"test","properties":{}}\n\n') })
        .mockResolvedValueOnce({ done: true }),
    };

    mockFetch.mockResolvedValue({
      ok: true,
      body: { getReader: () => mockReader },
    });

    const events: any[] = [];
    const stream = new SseStream();
    await stream.connect('http://localhost/event', {}, (e) => events.push(e), { aborted: false } as any);

    expect(events).toHaveLength(1);
    expect(events[0].type).toBe('test');
  });

  it('should handle multi-line data', async () => {
    const encoder = new TextEncoder();
    const mockReader = {
      read: vi.fn()
        .mockResolvedValueOnce({ done: false, value: encoder.encode('data: {"type":"msg","properties":{"part":{"id":"1","type":"text"}}}\ndata: {"type":"msg","properties":{"part":{"id":"1","type":"text","result":"done"}}}\n\n') })
        .mockResolvedValueOnce({ done: true }),
    };

    mockFetch.mockResolvedValue({
      ok: true,
      body: { getReader: () => mockReader },
    });

    const events: any[] = [];
    const stream = new SseStream();
    await stream.connect('http://localhost/event', {}, (e) => events.push(e), { aborted: false } as any);

    expect(events).toHaveLength(2);
  });

  it('should handle event: prefix for event type', async () => {
    const encoder = new TextEncoder();
    const mockReader = {
      read: vi.fn()
        .mockResolvedValueOnce({ done: false, value: encoder.encode('event: message\ndata: {"type":"test","properties":{}}\n\n') })
        .mockResolvedValueOnce({ done: true }),
    };

    mockFetch.mockResolvedValue({
      ok: true,
      body: { getReader: () => mockReader },
    });

    const events: any[] = [];
    const stream = new SseStream();
    await stream.connect('http://localhost/event', {}, (e) => events.push(e), { aborted: false } as any);

    expect(events).toHaveLength(1);
    expect(events[0].type).toBe('test');
  });

  it('should handle retry: directive', async () => {
    const encoder = new TextEncoder();
    const mockReader = {
      read: vi.fn()
        .mockResolvedValueOnce({ done: false, value: encoder.encode('retry: 5000\ndata: {"type":"test","properties":{}}\n\n') })
        .mockResolvedValueOnce({ done: true }),
    };

    mockFetch.mockResolvedValue({
      ok: true,
      body: { getReader: () => mockReader },
    });

    const stream = new SseStream();
    await stream.connect('http://localhost/event', {}, () => {}, { aborted: false } as any);
  });

  it('should retry on failure', async () => {
    const encoder = new TextEncoder();
    let attempts = 0;
    const mockReader = {
      read: vi.fn().mockImplementation(() => {
        attempts++;
        if (attempts < 2) throw new Error('Connection reset');
        return { done: true };
      }),
    };

    mockFetch.mockResolvedValue({
      ok: true,
      body: { getReader: () => mockReader },
    });

    const stream = new SseStream();
    stream.maxRetries = 1;

    await stream.connect('http://localhost/event', {}, () => {}, { aborted: false } as any);
  });

  it('should reject a successful response without a body', async () => {
    const response = { ok: true, body: null } as Response;
    const stream = new SseStream();

    await expect(stream.parse(response, () => {}, new AbortController().signal))
      .rejects.toThrow('SSE response has no body');
  });
});

import { describe, it, expect } from 'vitest';
import { normalizeDiff, NormalizedDiff } from './diffUtils';

describe('normalizeDiff', () => {
  it('should handle diff with path and content', () => {
    const input = {
      path: 'src/index.ts',
      content: '+1\n-2',
    };
    const result = normalizeDiff(input);
    expect(result.path).toBe('src/index.ts');
    expect(result.added).toBe(1);
    expect(result.deleted).toBe(1);
  });

  it('should handle diff with file field', () => {
    const input = {
      file: 'src/app.ts',
      content: '+5\n-3',
    };
    const result = normalizeDiff(input);
    expect(result.path).toBe('src/app.ts');
  });

  it('should use patch field as content', () => {
    const input = {
      path: 'test.js',
      patch: '+10\n-5',
    };
    const result = normalizeDiff(input);
    expect(result.content).toBe('+10\n-5');
  });

  it('should use provided added/deleted counts', () => {
    const input = {
      path: 'file.ts',
      added: 20,
      deleted: 10,
      content: '',
    };
    const result = normalizeDiff(input);
    expect(result.added).toBe(20);
    expect(result.deleted).toBe(10);
  });

  it('should count lines when added/deleted not provided', () => {
    const input = {
      path: 'test.ts',
      content: '+const a = 1;\n+const b = 2;\n-const c = 3;\n-const d = 4;\n+const e = 5;\n',
    };
    const result = normalizeDiff(input);
    expect(result.added).toBe(3);
    expect(result.deleted).toBe(2);
  });

  it('should ignore +++ and --- headers', () => {
    const input = {
      path: 'f.ts',
      content: '+++ b/src/f.ts\n- const a;\n+ const a = 1;\n',
    };
    const result = normalizeDiff(input);
    expect(result.added).toBe(1);
    expect(result.deleted).toBe(1);
  });

  it('should handle empty content', () => {
    const input = { path: 'empty.ts', content: '' };
    const result = normalizeDiff(input);
    expect(result.path).toBe('empty.ts');
    expect(result.added).toBe(0);
    expect(result.deleted).toBe(0);
  });

  it('should handle missing fields', () => {
    const input = { notAPath: 'value' };
    const result = normalizeDiff(input);
    expect(result.path).toBe('');
  });
});

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { ContextPart } from '../../extension/types';
import { CommandItem } from '../slashCommands';
import { SlashCommandPopup } from './SlashCommandPopup';
import { COLORS, flexRow, flexCenter, btnIcon, textSmall, inputBase } from '../styles';

interface FileResult {
  name: string;
  path: string;
}

interface Props {
  onSend: (text: string, context: ContextPart[]) => void;
  disabled: boolean;
  onSearchFiles: (query: string) => void;
  fileSearchResults: FileResult[];
  fileSearchQuery: string;
  onSlashCommand?: (cmd: CommandItem) => void;
  skills?: Array<{ name: string; description?: string }>;
}

export function BottomInput({ onSend, disabled, onSearchFiles, fileSearchResults, fileSearchQuery, onSlashCommand, skills }: Readonly<Props>) {
  const [text, setText] = useState('');
  const [attachments, setAttachments] = useState<ContextPart[]>([]);
  const [showFileSearch, setShowFileSearch] = useState(false);
  const [fileSearchInput, setFileSearchInput] = useState('');
  const [mentionEnabled, setMentionEnabled] = useState(false);
  const [showSlashPopup, setShowSlashPopup] = useState(false);
  const [slashFilter, setSlashFilter] = useState('');
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const fileSearchRef = useRef<HTMLDivElement>(null);
  const slashPopupRef = useRef<HTMLDivElement>(null);

  // Auto-resize textarea
  useEffect(() => {
    if (textareaRef.current) {
      textareaRef.current.style.height = 'auto';
      textareaRef.current.style.height = Math.min(textareaRef.current.scrollHeight, 120) + 'px';
    }
  }, [text]);

  // Close file search on outside click
  useEffect(() => {
    if (!showFileSearch) return;
    const handler = (e: MouseEvent) => {
      if (fileSearchRef.current && !fileSearchRef.current.contains(e.target as Node)) {
        setShowFileSearch(false);
      }
    };
    document.addEventListener('mousedown', handler);
    return () => document.removeEventListener('mousedown', handler);
  }, [showFileSearch]);

  // Close slash popup on outside click
  useEffect(() => {
    if (!showSlashPopup) return;
    const handler = (e: MouseEvent) => {
      if (slashPopupRef.current && !slashPopupRef.current.contains(e.target as Node) &&
          textareaRef.current && !textareaRef.current.contains(e.target as Node)) {
        setShowSlashPopup(false);
      }
    };
    document.addEventListener('mousedown', handler);
    return () => document.removeEventListener('mousedown', handler);
  }, [showSlashPopup]);

  const handleSend = () => {
    if ((!text.trim() && attachments.length === 0) || disabled) return;
    onSend(text.trim(), attachments);
    setText('');
    setAttachments([]);
    setShowSlashPopup(false);
  };

  const handleSlashSelect = (cmd: CommandItem) => {
    if (cmd.type === 'skill') {
      setText(`/${cmd.command} `);
    } else {
      setText('');
    }
    setShowSlashPopup(false);
    onSlashCommand?.(cmd);
    setTimeout(() => textareaRef.current?.focus(), 0);
  };

  const handleKeyDown = (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
    if (e.key === 'Enter' && !e.shiftKey && !disabled) {
      if (showSlashPopup) {
        // Let the popup handle Enter
        return;
      }
      e.preventDefault();
      handleSend();
    }
  };

  const handleChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    const val = e.target.value;
    setText(val);

    // Detect @mention
    const lastAt = val.lastIndexOf('@');
    if (lastAt >= 0) {
      const afterAt = val.slice(lastAt + 1);
      if (!afterAt.includes(' ') && afterAt.length < 50) {
        setMentionEnabled(true);
        setFileSearchInput(afterAt);
        setShowFileSearch(true);
        onSearchFiles(afterAt);
      } else {
        if (mentionEnabled) setMentionEnabled(false);
      }
    } else {
      if (mentionEnabled) setMentionEnabled(false);
    }

    // Detect / slash command at start
    const trimmed = val.trimStart();
    if (trimmed.startsWith('/') && !val.includes(' ')) {
      const afterSlash = trimmed.slice(1);
      setSlashFilter(afterSlash);
      setShowSlashPopup(true);
      setShowFileSearch(false);
    } else {
      setShowSlashPopup(false);
    }
  };

  const handlePaste = useCallback(async (e: React.ClipboardEvent) => {
    const items = e.clipboardData?.items;
    if (!items) return;

    for (let i = 0; i < items.length; i++) {
      if (items[i].type.startsWith('image/')) {
        e.preventDefault();
        const file = items[i].getAsFile();
        if (!file) continue;

        const reader = new FileReader();
        reader.onload = () => {
          const dataUrl = reader.result as string;
          const base64 = dataUrl.split(',')[1];
          setAttachments((prev) => [
            ...prev,
            { type: 'image', name: file.name || 'paste.png', data: base64, mimeType: file.type || 'image/png' },
          ]);
        };
        reader.readAsDataURL(file);
      }
    }
  }, []);

  const handleFileSelect = (file: FileResult) => {
    const val = text;
    const lastAt = val.lastIndexOf('@');
    if (lastAt >= 0) {
      setText(val.slice(0, lastAt) + ' ');
    }
    setAttachments((prev) => [...prev, { type: 'file', name: file.name, path: file.path }]);
    setShowFileSearch(false);
    setMentionEnabled(false);
    setTimeout(() => textareaRef.current?.focus(), 0);
  };

  const removeAttachment = (index: number) => {
    setAttachments((prev) => prev.filter((_, i) => i !== index));
  };

  const handlePlusClick = () => {
    if (showFileSearch) {
      setShowFileSearch(false);
      return;
    }
    setFileSearchInput('');
    setShowFileSearch(true);
    onSearchFiles('');
  };

  const handleFileSearchKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && fileSearchResults.length > 0) {
      handleFileSelect(fileSearchResults[0]);
    }
    if (e.key === 'Escape') {
      setShowFileSearch(false);
    }
  };

  const canSend = text.trim().length > 0 || attachments.length > 0;

  return (
    <div style={{ padding: '12px 16px', backgroundColor: '#181825', position: 'relative' }}>
      {/* Slash Command Popup */}
      {showSlashPopup && (
        <div ref={slashPopupRef}>
          <SlashCommandPopup
            filter={slashFilter}
            skills={skills || []}
            onSelect={handleSlashSelect}
            onClose={() => setShowSlashPopup(false)}
          />
        </div>
      )}
      {/* File Search Popup */}
      {showFileSearch && (
        <div
          ref={fileSearchRef}
          style={{
            position: 'absolute',
            bottom: '100%',
            left: 16,
            right: 16,
            maxHeight: 250,
