                alignItems: 'center',
                gap: 6,
                padding: '4px 8px',
                backgroundColor: '#313244',
                borderRadius: 8,
                fontSize: 12,
                color: '#cdd6f4',
                maxWidth: '100%',
              }}
            >
              {att.type === 'image' ? (
                <>
                  <img
                    src={`data:${att.mimeType};base64,${att.data}`}
                    alt=""
