                            {messages[provider.id]}
                          </div>
                        )}
                      </div>
                    </div>
                  );
                })}
              </div>
            )
          )}
        </div>
      </div>
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import { postMessage, onMessage } from '../vscode-api';

interface Props {
  onClose: () => void;
  onSelect: (sessionId: string) => void;
}

interface SessionItem {
  id: string;
  title?: string;
  time?: { created?: number };
}

export function SessionListPopup({ onClose, onSelect }: Props) {
  const [sessions, setSessions] = useState<SessionItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [showDeleteMenu, setShowDeleteMenu] = useState(false);

  useEffect(() => {
    postMessage({ type: 'getSessions' });
    const unsubscribe = onMessage((msg) => {
      if (msg.type === 'sessionList') {
        setSessions(Array.isArray(msg.payload) ? msg.payload : []);
        setLoading(false);
      }
    });
    return unsubscribe;
  }, []);

  const handleDelete = (e: React.MouseEvent, sessionId: string) => {
    e.stopPropagation();
    postMessage({ type: 'deleteSession', payload: { sessionId } });
    setSessions((prev) => prev.filter((s) => s.id !== sessionId));
  };

  const handleDeleteOld = async (days: number) => {
    const now = Date.now();
    const cutoff = days === 0 ? 0 : now - days * 24 * 60 * 60 * 1000;
    const oldSessions = cutoff === 0
      ? sessions
      : sessions.filter(s => s.time?.created && s.time.created < cutoff);
    for (const s of oldSessions) {
      postMessage({ type: 'deleteSession', payload: { sessionId: s.id } });
    }
    setSessions(prev => prev.filter(s => !oldSessions.includes(s)));
    setShowDeleteMenu(false);
  };

  const getSessionAge = (ts?: number): string => {
    if (!ts) return '';
    const days = Math.floor((Date.now() - ts) / (24 * 60 * 60 * 1000));
    if (days === 0) return 'Today';
    if (days === 1) return '1 day ago';
    return `${days} days ago`;
  };

  const formatDate = (ts?: number) => {
    if (!ts) return '';
    const d = new Date(ts);
    const locale = (window as any).vscode?.env?.language || navigator.language || 'en-US';
    return d.toLocaleDateString(locale, { day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit' });
  };

  const oldCount = sessions.filter(s => s.time?.created && s.time.created < Date.now() - 7 * 24 * 60 * 60 * 1000).length;

  return (
    <div
      style={{
        position: 'absolute', top: 0, left: 0, right: 0, bottom: 0,
        backgroundColor: 'rgba(0,0,0,0.5)', zIndex: 200,
        display: 'flex', alignItems: 'flex-end', justifyContent: 'center',
      }}
      onClick={(e) => { if (e.target === e.currentTarget) onClose(); }}
    >
      <div
        style={{
          backgroundColor: '#1e1e2e', border: '1px solid #313244', borderBottom: 'none',
          borderRadius: '16px 16px 0 0', width: '100%', maxHeight: '75vh',
          display: 'flex', flexDirection: 'column', overflow: 'hidden',
          boxShadow: '0 -4px 20px rgba(0,0,0,0.4)',
        }}
      >
        {/* Header */}
        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', padding: '14px 16px', borderBottom: '1px solid #313244', flexShrink: 0 }}>
          <div>
            <div style={{ fontSize: 16, fontWeight: 600, color: '#cdd6f4' }}>Session History</div>
            <div style={{ fontSize: 11, color: '#585b70', marginTop: 2 }}>
              {loading ? 'Loading...' : `${sessions.length} session${sessions.length !== 1 ? 's' : ''}`}
            </div>
          </div>
          <div style={{ display: 'flex', gap: 8 }}>
            {sessions.length > 0 && (
              <div style={{ position: 'relative' }}>
                <button
                  onClick={() => setShowDeleteMenu(!showDeleteMenu)}
                  style={{
                    background: 'none', border: '1px solid #313244', color: '#a6adc8', cursor: 'pointer',
                    fontSize: 12, padding: '6px 10px', borderRadius: 6,
                  }}
                  onMouseEnter={(e) => (e.currentTarget.style.borderColor = '#585b70')}
                  onMouseLeave={(e) => (e.currentTarget.style.borderColor = '#313244')}
                >
                  Delete old Ôû╝
                </button>
                {showDeleteMenu && (
                  <div style={{
                    position: 'absolute', right: 0, top: '100%', marginTop: 4,
                    backgroundColor: '#181825', border: '1px solid #313244',
                    borderRadius: 8, padding: '4px 0', minWidth: 140, zIndex: 10,
                  }}>
                    {[
                      { days: 7, label: 'Older than 7 days' },
                      { days: 30, label: 'Older than 30 days' },
                      { days: 90, label: 'Older than 90 days' },
                      { days: 0, label: 'All sessions' },
                    ].map(opt => (
                      <div
                        key={opt.days}
                        onClick={() => handleDeleteOld(opt.days)}
                        style={{
                          padding: '8px 12px', cursor: 'pointer', fontSize: 12, color: '#cdd6f4',
                        }}
                        onMouseEnter={(e) => (e.currentTarget.style.backgroundColor = '#313244')}
                        onMouseLeave={(e) => (e.currentTarget.style.backgroundColor = 'transparent')}
                      >
                        {opt.label}
                      </div>
                    ))}
                  </div>
                )}
              </div>
            )}
            <button onClick={onClose} style={{ background: 'none', border: 'none', color: '#a6adc8', cursor: 'pointer', fontSize: 20, padding: 4, lineHeight: 1 }}>Ô£ò</button>
          </div>
        </div>

        {/* List */}
        <div style={{ flex: 1, overflowY: 'auto', padding: '8px 12px' }}>
          {loading ? (
            <div style={{ textAlign: 'center', padding: 20, color: '#585b70', fontSize: 13 }}>Loading...</div>
          ) : sessions.length === 0 ? (
            <div style={{ textAlign: 'center', padding: 20, color: '#585b70', fontSize: 13 }}>No sessions yet</div>
          ) : (
            sessions.map((s) => (
              <div
                key={s.id}
                onClick={() => onSelect(s.id)}
                style={{
                  display: 'flex', alignItems: 'center', justifyContent: 'space-between',
                  padding: '12px 14px', borderRadius: 10, backgroundColor: '#181825',
                  marginBottom: 6, cursor: 'pointer',
                }}
                onMouseEnter={(e) => (e.currentTarget.style.backgroundColor = '#313244')}
                onMouseLeave={(e) => (e.currentTarget.style.backgroundColor = '#181825')}
              >
                <div style={{ flex: 1, minWidth: 0 }}>
                  <div style={{ fontSize: 13, color: '#cdd6f4', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                    {s.title || `Session ${s.id.slice(0, 8)}`}
                  </div>
                  <div style={{ fontSize: 11, color: '#585b70', marginTop: 2 }}>
                    {s.time?.created ? `${formatDate(s.time.created)} ┬À ${getSessionAge(s.time.created)}` : ''}
                  </div>
                </div>
                <button
                  onClick={(e) => handleDelete(e, s.id)}
                  style={{
                    background: 'none', border: 'none', color: '#585b70', cursor: 'pointer',
                    padding: '4px 8px', borderRadius: 4, fontSize: 12, marginLeft: 8,
                  }}
                  onMouseEnter={(e) => (e.currentTarget.style.color = '#f38ba8')}
                  onMouseLeave={(e) => (e.currentTarget.style.color = '#585b70')}
                  title="Delete"
                >
                  ­şùæ
                </button>
              </div>
            ))
          )}
        </div>
      </div>
    </div>
  );
}

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { CommandItem, BUILTIN_COMMANDS, getCommandColor } from '../slashCommands';

interface Props {
  filter: string;
  skills: Array<{ name: string; description?: string }>;
  onSelect: (cmd: CommandItem) => void;
  onClose: () => void;
}

export function SlashCommandPopup({ filter, skills, onSelect, onClose }: Readonly<Props>) {
  const [selectedIndex, setSelectedIndex] = useState(0);
  const [hoveredIndex, setHoveredIndex] = useState(-1);
  const popupRef = useRef<HTMLDivElement>(null);

  const items: CommandItem[] = [
    ...BUILTIN_COMMANDS,
    ...skills.map((s) => ({
      type: 'skill' as const,
      command: s.name,
      label: s.name,
      description: s.description || 'Skill instructions',
      skillName: s.name,
    })),
  ];

  const filtered = filter
    ? items.filter((c) => c.command.toLowerCase().startsWith(filter.toLowerCase()))
    : items;

  useEffect(() => {
    setSelectedIndex(0);
  }, [filter]);

  const handleKeyDown = useCallback((e: KeyboardEvent) => {
    if (e.key === 'ArrowDown') {
      e.preventDefault();
      setSelectedIndex((i) => Math.min(i + 1, filtered.length - 1));
    } else if (e.key === 'ArrowUp') {
      e.preventDefault();
      setSelectedIndex((i) => Math.max(i - 1, 0));
    } else if (e.key === 'Enter' || e.key === 'Tab') {
      e.preventDefault();
      if (filtered[selectedIndex]) {
        onSelect(filtered[selectedIndex]);
      }
    } else if (e.key === 'Escape') {
      e.preventDefault();
      onClose();
    }
  }, [filtered, selectedIndex, onSelect, onClose]);

  useEffect(() => {
    if (filtered.length === 0) return;
    document.addEventListener('keydown', handleKeyDown);
    return () => document.removeEventListener('keydown', handleKeyDown);
  }, [handleKeyDown, filtered.length]);

  // Scroll selected into view
  useEffect(() => {
    const el = popupRef.current?.querySelector(`[data-index="${selectedIndex}"]`);
    el?.scrollIntoView({ block: 'nearest' });
  }, [selectedIndex]);

  if (filtered.length === 0) return null;

  return (
    <div
      ref={popupRef}
      style={{
        position: 'absolute',
        bottom: '100%',
        left: 16,
        right: 16,
        maxHeight: 280,
        overflowY: 'auto',
        backgroundColor: '#1e1e2e',
        border: '1px solid #45475a',
        borderRadius: 12,
        boxShadow: '0 -4px 20px rgba(0,0,0,0.4)',
        zIndex: 100,
      }}
    >
      <div style={{ padding: '6px 12px', borderBottom: '1px solid #313244', fontSize: 11, color: '#6c7086' }}>
        Commands &amp; Skills
      </div>
      {filtered.map((cmd, i) => {
        const color = getCommandColor(cmd);
        const isSelected = i === selectedIndex;
        return (
          <div
            key={`${cmd.type}_${cmd.command}`}
            data-index={i}
            onClick={() => onSelect(cmd)}
            onMouseEnter={() => { setSelectedIndex(i); setHoveredIndex(i); }}
            style={{
              padding: '8px 12px',
              cursor: 'pointer',
              display: 'flex',
              alignItems: 'center',
              gap: 8,
              backgroundColor: isSelected ? '#313244' : 'transparent',
              transition: 'background-color 0.1s',
            }}
          >
            <span style={{
              width: 8, height: 8, borderRadius: '50%',
              backgroundColor: color?.text || '#6c7086',
              flexShrink: 0,
            }} />
            <div style={{ flex: 1, minWidth: 0 }}>
              <div style={{ fontSize: 13, color: '#cdd6f4', fontWeight: 500 }}>
                <span style={{ color: color?.text || '#6c7086' }}>/{cmd.command}</span>
                {cmd.type === 'skill' && (
                  <span style={{ fontSize: 10, color: '#6c7086', marginLeft: 6, fontWeight: 400 }}>skill</span>
                )}
              </div>
              <div style={{ fontSize: 11, color: '#6c7086', marginTop: 1, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                {cmd.description}
              </div>
            </div>
          </div>
        );
      })}
    </div>
  );
}

import { MouseEvent, useCallback } from 'react';

export const hover = (style: React.CSSProperties) => (e: MouseEvent<HTMLElement>) => {
  Object.assign(e.currentTarget.style, style);
};

export const unhover = () => (e: MouseEvent<HTMLElement>) => {
  e.currentTarget.style.cssText = '';
};

export const setColor = (color: string) => (e: MouseEvent<HTMLElement>) => {
  e.currentTarget.style.color = color;
};

export const clearStyle = (e: MouseEvent<HTMLElement>) => {
  e.currentTarget.style.cssText = '';
};

import { useState, useCallback, useEffect, useRef } from 'react';
import { GitInfo, ProviderListResult, ProviderModel, ContextPart } from '../../extension/types';
import { postMessage } from '../vscode-api';
import { CommandItem } from '../slashCommands';

export interface ModelItem {
  id: string;
  name: string;
  providerId: string;
}

export function useModelManager() {
  const [model, setModel] = useState('');
  const [mode, setMode] = useState('build');
  const [gitInfo, setGitInfo] = useState<GitInfo>({
    branch: 'main',
    lastCommitTime: 'a minute ago',
    projectPath: 'C:/Projects/opencode_sidebar',
  });
  const [availableModels, setAvailableModels] = useState<ModelItem[]>([]);
  const [hiddenModels, setHiddenModels] = useState<Record<string, boolean>>({});
  const [providersLoaded, setProvidersLoaded] = useState(false);
  const [skills, setSkills] = useState<Array<{ name: string; description?: string }>>([]);
  const [fileSearchResults, setFileSearchResults] = useState<Array<{ name: string; path: string }>>([]);
  const [fileSearchQuery, setFileSearchQuery] = useState('');
  const [revertActive, setRevertActive] = useState(false);
  const [confirmDialog, setConfirmDialog] = useState<{ message: string; onConfirm: () => void } | null>(null);
  const [readPermissionPrompt, setReadPermissionPrompt] = useState<{ filePath: string; reason: string; requestId: string } | null>(null);
  const [showProviders, setShowProviders] = useState(false);
  const [showSessions, setShowSessions] = useState(false);

  const pendingRevertRef = useRef<string | null>(null);

  useEffect(() => {
    if (model) {
      postMessage({ type: 'saveModel', payload: { model } });
    }
  }, [model]);

  const toggleModelVisibility = useCallback((modelId: string) => {
    setHiddenModels((prev) => ({ ...prev, [modelId]: !prev[modelId] }));
  }, []);

  const handleToggleAllModels = useCallback((providerId: string, show: boolean) => {
    setHiddenModels((prev) => {
      const next = { ...prev };
      for (const m of availableModels) {
        if (m.providerId === providerId) {
          if (show) delete next[m.id];
          else next[m.id] = true;
        }
      }
      return next;
    });
  }, [availableModels]);

  const processProviderList = useCallback((result: ProviderListResult) => {
    const all = result.all || [];
    const conn = result.connected || [];
    const models: ModelItem[] = [];
    for (const provider of all) {
      if (conn.includes(provider.id)) {
        for (const [modelId, modelInfo] of Object.entries(provider.models || {})) {
          const info = modelInfo as ProviderModel;
          models.push({
            id: `${provider.id}/${modelId}`,
            name: info.name || modelId,
            providerId: provider.id,
          });
        }
      }
    }
    models.sort((a, b) => {
      const aIsPinned = a.providerId === 'opencode' || a.providerId === 'opencode-go' ? 0 : 1;
      const bIsPinned = b.providerId === 'opencode' || b.providerId === 'opencode-go' ? 0 : 1;
      if (aIsPinned !== bIsPinned) return aIsPinned - bIsPinned;
      if (a.providerId !== b.providerId) return a.providerId.localeCompare(b.providerId);
      return a.name.localeCompare(b.name);
    });

    setAvailableModels(models);
    setProvidersLoaded(true);
  }, []);

  const tryAutoSelectModel = useCallback((models: ModelItem[], currentModel: string, hidden: Record<string, boolean>) => {
    if (!currentModel) {
      const visible = models.filter((m) => !hidden[m.id]);
      if (visible.length > 0) {
        setModel(visible[0].id);
      }
    }
  }, []);

  return {
    model, setModel, mode, setMode,
    gitInfo, setGitInfo,
    availableModels, setAvailableModels,
    hiddenModels, setHiddenModels,
    providersLoaded, setProvidersLoaded,
    skills, setSkills,
    fileSearchResults, setFileSearchResults,
    fileSearchQuery, setFileSearchQuery,
    revertActive, setRevertActive,
    confirmDialog, setConfirmDialog,
    readPermissionPrompt, setReadPermissionPrompt,
    showProviders, setShowProviders,
    showSessions, setShowSessions,
    pendingRevertRef,
    toggleModelVisibility, handleToggleAllModels,
    processProviderList, tryAutoSelectModel,
  };
}
